#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
A2A Mesh — Későn csatlakozóknak utolsó N üzenet automatikus visszajátszása.

Ez a modul egy üzenet-puffert (ring buffer) valósít meg, amely az utolsó N
üzenetet tárolja, és amikor egy új kliens (peer) csatlakozik a mesh hálózathoz,
automatikusan visszajátszza neki a tárolt üzeneteket, így a későn csatlakozók
sem maradnak le a korábbi beszélgetésből.

Futtatható a repó gyökeréből:
    python a2a_mesh/replay_buffer.py
"""

from __future__ import annotations

import asyncio
import json
import logging
import time
import uuid
from collections import deque
from dataclasses import dataclass, field, asdict
from typing import Any, Callable, Deque, Dict, List, Optional, Set

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
)
logger = logging.getLogger("a2a-mesh.replay")


# ---------------------------------------------------------------------------
# Data structures
# ---------------------------------------------------------------------------

@dataclass(frozen=True)
class MeshMessage:
    """Egy mesh üzenet, amit a hálózaton terjesztünk."""
    id: str
    topic: str
    sender: str
    payload: Any
    timestamp: float

    def to_dict(self) -> dict:
        return asdict(self)

    def to_json(self) -> str:
        return json.dumps(self.to_dict(), ensure_ascii=False)

    @classmethod
    def from_dict(cls, data: dict) -> "MeshMessage":
        return cls(**data)

    @classmethod
    def from_json(cls, raw: str) -> "MeshMessage":
        return cls.from_dict(json.loads(raw))


@dataclass
class Peer:
    """Egy csatlakozott peer adiv a mesh-ben."""
    peer_id: str
    topics: Set[str] = field(default_factory=set)
    connected_at: float = field(default_factory=time.time)
    is_new: bool = True  # még nem kapott replay-t
    writer: Optional[asyncio.StreamWriter] = None

    def subscribes_to(self, topic: str) -> bool:
        # Üres topic-set = mindenre feliratkozott
        return len(self.topics) == 0 or topic in self.topics


# ---------------------------------------------------------------------------
# ReplayBuffer — az utolsó N üzenet tárolása
# ---------------------------------------------------------------------------

class ReplayBuffer:
    """
    Ring buffer, amely az utolsó *max_size* üzenetet tárolja topic-onként.
    Amikor egy új peer csatlakozik, a buffer visszajátszza neki a releváns
    üzeneteket (topic szűrés alapján).
    """

    def __init__(self, max_size: int = 100) -> None:
        if max_size <= 0:
            raise ValueError("max_size must be positive")
        self.max_size = max_size
        self._buffer: Deque[MeshMessage] = deque(maxlen=max_size)
        self._lock = asyncio.Lock()

    async def add(self, message: MeshMessage) -> None:
        async with self._lock:
            self._buffer.append(message)
            logger.debug("Buffered message %s (topic=%s, total=%d)",
                         message.id, message.topic, len(self._buffer))

    async def get_replay_for(self, peer: Peer) -> List[MeshMessage]:
        """Visszaadja azokat az üzeneteket, amiket a peer-nek kapnia kell."""
        async with self._lock:
            result: List[MeshMessage] = []
            for msg in self._buffer:
                if peer.subscribes_to(msg.topic):
                    result.append(msg)
            return result

    async def snapshot(self) -> List[MeshMessage]:
        async with self._lock:
            return list(self._buffer)

    def __len__(self) -> int:
        return len(self._buffer)


# ---------------------------------------------------------------------------
# MeshNode — a hálózati csomópont replay logikával
# ---------------------------------------------------------------------------

class MeshNode:
    """
    Egyszerű TCP-alapú mesh csomópont, amely:
      - fogadja a bejövő kapcsolatokat (peer-eket),
      - fogadja a publikált üzeneteket,
      - továbbítja az üzeneteket a feliratkozott peer-eknek,
      - új peer csatlakozásakor visszajátszza az utolsó N üzenetet.
    """

    def __init__(
        self,
        node_id: str,
        host: str = "127.0.0.1",
        port: int = 0,
        replay_size: int = 50,
    ) -> None:
        self.node_id = node_id
        self.host = host
        self.port = port
        self.replay_buffer = ReplayBuffer(max_size=replay_size)
        self.peers: Dict[str, Peer] = {}
        self._server: Optional[asyncio.AbstractServer] = None
        self._lock = asyncio.Lock()

    # -- lifecycle -----------------------------------------------------------

    async def start(self) -> None:
        self._server = await asyncio.start_server(
            self._handle_connection, self.host, self.port
        )
        sock = self._server.sockets[0]
        self.port = sock.getsockname()[1]
        logger.info("MeshNode '%s' listening on %s:%d (replay=%d)",
                    self.node_id, self.host, self.port,
                    self.replay_buffer.max_size)

    async def stop(self) -> None:
        if self._server:
            self._server.close()
            await self._server.wait_closed()
        logger.info("MeshNode '%s' stopped.", self.node_id)

    # -- connection handling -------------------------------------------------

    async def _handle_connection(
        self, reader: asyncio.StreamReader, writer: asyncio.StreamWriter
    ) -> None:
        peer_addr = writer.get_extra_info("peername")
        peer_id = str(uuid.uuid4())[:8]
        peer = Peer(peer_id=peer_id, writer=writer)
        async with self._lock:
            self.peers[peer_id] = peer
        logger.info("Peer %s connected from %s", peer_id, peer_addr)

        try:
            # 1) Olvassuk a feliratkozási információt (első sor JSON)
            hello_raw = await reader.readline()
            if not hello_raw:
                return
            hello = json.loads(hello_raw.decode().strip())
            peer.topics = set(hello.get("topics", []))
            logger.info("Peer %s subscribed to topics: %s",
                        peer_id, peer.topics or "(all)")

            # 2) Visszajátszás: utolsó N üzenet küldése
            await self._replay_to(peer)

            # 3) Ezután a peer küldhet üzeneteket / élvezheti a live stream-et
            while True:
                line = await reader.readline()
                if not line:
                    break
                msg = MeshMessage.from_json(line.decode().strip())
                await self.publish(msg, originator=peer_id)

        except (json.JSONDecodeError, KeyError, ConnectionResetError) as exc:
            logger.warning("Peer %s error: %s", peer_id, exc)
        finally:
            async with self._lock:
                self.peers.pop(peer_id, None)
            writer.close()
            try:
                await writer.wait_closed()
            except Exception:
                pass
            logger.info("Peer %s disconnected", peer_id)

    # -- replay --------------------------------------------------------------

    async def _replay_to(self, peer: Peer) -> None:
        """Visszajátszza a bufferelt üzeneteket az új peer-nek."""
        messages = await self.replay_buffer.get_replay_for(peer)
        if not messages:
            logger.info("No messages to replay to peer %s", peer.peer_id)
            return

        # Replay envelope küldése, hogy a peer tudja: ez visszajátszás
        envelope = {
            "type": "replay",
            "count": len(messages),
            "node_id": self.node_id,
        }
        assert peer.writer is not None
        peer.writer.write((json.dumps(envelope) + "\n").encode())
        await peer.writer.drain()

        for msg in messages:
            peer.writer.write((msg.to_json() + "\n").encode())
        await peer.writer.drain()
        peer.is_new = False
        logger.info("Replayed %d messages to peer %s", len(messages), peer.peer_id)

    # -- publish -------------------------------------------------------------

    async def publish(self, message: MeshMessage, originator: str = "") -> None:
        """Publikál egy üzenetet: buffereli + továbbítja a feliratkozott peer-eknek."""
        # Bufferelés (későn csatlakozók miatt)
        await self.replay_buffer.add(message)

        # Live továbbítás a már csatlakozott, feliratkozott peer-eknek
        # (kivéve a küldőt)
        async with self._lock:
            recipients = [
                p for p in self.peers.values()
                if p.peer_id != originator
                and not p.is_new  # már megkapta a replay-t
                and p.writer is not None
                and p.subscribes_to(message.topic)
            ]

        for p in recipients:
            try:
                assert p.writer is not None
                p.writer.write((message.to_json() + "\n").encode())
                await p.writer.drain()
            except Exception as exc:
                logger.warning("Failed to send to peer %s: %s", p.peer_id, exc)

        logger.info("Published msg %s (topic=%s) from %s to %d live peers",
                    message.id, message.topic, message.sender, len(recipients))


# ---------------------------------------------------------------------------
# Demo client — szimulál egy későn csatlakozó peer-t
# ---------------------------------------------------------------------------

async def simulate_client(
    name: str,
    host: str,
    port: int,
    topics: Optional[List[str]] = None,
    receive_count: int = 10,
    timeout: float = 5.0,
) -> List[MeshMessage]:
    """Csatlakozik a mesh node-hoz és fogadja a replay + live üzeneteket."""
    reader, writer = await asyncio.open_connection(host, port)

    hello = {"topics": topics or []}
    writer.write((json.dumps(hello) + "\n").encode())
    await writer.drain()

    received: List[MeshMessage] = []
    try:
        # Első sor: replay envelope (vagy közvetlen üzenet)
        envelope_raw = await asyncio.wait_for(reader.readline(), timeout=timeout)
        if envelope_raw:
            first = json.loads(envelope_raw.decode().strip())
            if first.get("type") == "replay":
                count = first["count"]
                print(f"  [{name}] Received replay envelope: {count} messages")
                for _ in range(count):
                    raw = await asyncio.wait_for(reader.readline(), timeout=timeout)
                    if raw:
                        msg = MeshMessage.from_json(raw.decode().strip())
                        received.append(msg)
            else:
                # Ez egy live üzenet volt
                msg = MeshMessage.from_dict(first)
                received.append(msg)
    except asyncio.TimeoutError:
        pass

    writer.close()
    try:
        await writer.wait_closed()
    except Exception:
        pass
    return received


# ---------------------------------------------------------------------------
# Main demo
# ---------------------------------------------------------------------------

async def main() -> None:
    """
    Demo forgatókönyv:
      1. Elindítunk egy MeshNode-ot replay buffer-rel (N=50).
      2. Publikálunk 5 üzenetet (még nincs csatlakozott peer).
      3. Csatlakozik egy "késői" peer — és megkapja mind az 5 üzenetet
         automatikus visszajátszásként.
      4. Publikálunk még 2 üzenetet — a késői peer már nem kapja meg
         (mert lecsatlakolt), de egy új peer, aki feliratkozik csak a
         "news" topic-ra, csak az arra vonatkozó üzeneteket kapja meg.
    """
    print("=" * 70)
    print("A2A Mesh — Későn csatlakozóknak utolsó N üzenet visszajátszása")
    print("=" * 70)

    node = MeshNode(node_id="node-1", host="127.0.0.1", port=0, replay_size=50)
    await node.start()

    # --- 1) Publikálunk 5 üzenetet, mielőtt bárki csatlakozna ---------------
    print("\n[1] Publishing 5 messages before any peer connects...")
    topics_cycle = ["general", "news", "general", "alerts", "news"]
    for i in range(5):
        msg = MeshMessage(
            id=str(uuid.uuid4())[:8],
            topic=topics_cycle[i],
            sender="early-bird",
            payload={"text": f"Message #{i+1}", "seq": i + 1},
            timestamp=time.time(),
        )
        await node.publish(msg)
        print(f"    Published: topic={msg.topic} payload={msg.payload}")

    await asyncio.sleep(0.3)

    # --- 2) Későn csatlakozó peer — minden topic ----------------------------
    print("\n[2] Late joiner 'latecomer-all' connects (subscribed to ALL topics)...")
    replayed_all = await simulate_client(
        "latecomer-all", node.host, node.port, topics=[], receive_count=10
    )
    print(f"    Latecomer received {len(replayed_all)} replayed messages:")
    for m in replayed_all:
        print(f"      -> topic={m.topic} payload={m.payload}")

    assert len(replayed_all) == 5, f"Expected 5 replayed, got {len(replayed_all)}"

    # --- 3) Későn csatlakozó peer — csak "news" topic -----------------------
    print("\n[3] Late joiner 'latecomer-news' connects (subscribed to 'news' only)...")
    replayed_news = await simulate_client(
        "latecomer-news", node.host, node.port, topics=["news"], receive_count=10
    )
    print(f"    Latecomer-news received {len(replayed_news)} replayed messages:")
    for m in replayed_news:
        print(f"      -> topic={m.topic} payload={m.payload}")

    # A "news" topic-ból 2 üzenet volt (#2 és #5)
    assert len(replayed_news) == 2, f"Expected 2 replayed, got {len(replayed_news)}"
    assert all(m.topic == "news" for m in replayed_news)

    # --- 4) Buffer overflow teszt -------------------------------------------
    print("\n[4] Publishing 60 more messages to test buffer overflow (max=50)...")
    for i in range(60):
        msg = MeshMessage(
            id=str(uuid.uuid4())[:8],
            topic="general",
            sender="flood",
            payload={"text": f"Flood #{i+1}", "seq": i + 1},
            timestamp=time.time(),
        )
        await node.publish(msg)

    snapshot = await node.replay_buffer.snapshot()
    print(f"    Buffer now holds {len(snapshot)} messages (max=50)")
    assert len(snapshot) == 50, f"Expected 50, got {len(snapshot)}"

    # --- 5) Új peer — csak az utolsó 50-et kapja meg ------------------------
    print("\n[5] New late joiner after flood — should get exactly 50 messages...")
    replayed_flood = await simulate_client(
        "latecomer-flood", node.host, node.port, topics=[], receive_count=60
    )
    print(f"    Latecomer-flood received {len(replayed_flood)} replayed messages")
    assert len(replayed_flood) == 50, f"Expected 50, got {len(replayed_flood)}"

    # --- Összegzés -----------------------------------------------------------
    print("\n" + "=" * 70)
    print("ALL TESTS PASSED ✓")
    print(f"  - Early messages replayed to late joiner:        {len(replayed_all)}")
    print(f"  - Topic-filtered replay (news only):             {len(replayed_news)}")
    print(f"  - Buffer overflow correctly capped at 50:        {len(snapshot)}")
    print(f"  - Post-flood late joiner got exactly 50:         {len(replayed_flood)}")
    print("=" * 70)

    await node.stop()


if __name__ == "__main__":
    asyncio.run(main())